import { Component, Element, Event, EventEmitter, Host, Prop, h } from '@stencil/core';
import { Offset, Wideness } from '../../../types';

/**
 * @slot default - default slot for the content of the grid-col
 */
@Component({
  tag: 'groupui-grid-col',
  styleUrl: 'grid-col.scss',
  shadow: true,
})
export class GridCol {
  /**
   * size of the column for breakpoint xs
   */
  @Prop({ reflect: true }) readonly xs: Wideness;

  /**
   * size of the column for breakpoint s
   */
  @Prop({ reflect: true }) readonly s: Wideness;

  /**
   * size of the column for breakpoint m
   */
  @Prop({ reflect: true }) readonly m: Wideness;

  /**
   * size of the column for breakpoint l
   */
  @Prop({ reflect: true }) readonly l: Wideness;

  /**
   * size of the column for breakpoint xl
   */
  @Prop({ reflect: true }) readonly xl: Wideness;

  /**
   * size of the column for breakpoint xxl
   */
  @Prop({ reflect: true }) readonly xxl: Wideness;

  /**
   * offset of the column for breakpoint xs
   */
  @Prop({ reflect: true }) readonly offsetXs: Offset;

  /**
   * offset of the column for breakpoint s
   */
  @Prop({ reflect: true }) readonly offsetS: Offset;

  /**
   * offset of the column for breakpoint m
   */
  @Prop({ reflect: true }) readonly offsetM: Offset;

  /**
   * offset of the column for breakpoint l
   */
  @Prop({ reflect: true }) readonly offsetL: Offset;

  /**
   * offset of the column for breakpoint xl
   */
  @Prop({ reflect: true }) readonly offsetXl: Offset;

  /**
   * offset of the column for breakpoint xxl
   */
  @Prop({ reflect: true }) readonly offsetXxl: Offset;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    if (this.isOffsetSet()) {
      const spacerCol = document.createElement('groupui-grid-col');
      spacerCol.setAttribute('xs', this.offsetXs ? `${this.offsetXs}` : '0');
      if (this.offsetS) spacerCol.setAttribute('s', `${this.offsetS}`);
      if (this.offsetM) spacerCol.setAttribute('m', `${this.offsetM}`);
      if (this.offsetL) spacerCol.setAttribute('l', `${this.offsetL}`);
      if (this.offsetXl) spacerCol.setAttribute('xl', `${this.offsetXl}`);
      if (this.offsetXxl) spacerCol.setAttribute('xxl', `${this.offsetXxl}`);
      spacerCol.classList.add('spacer');
      spacerCol.style.visibility = 'hidden';

      this.host.closest('groupui-grid-row').insertBefore(spacerCol, this.host);
    }

    this.groupuiDidLoad.emit();
  }

  private isOffsetSet(): boolean {
    return !!(this.offsetXs || this.offsetS || this.offsetM || this.offsetL || this.offsetXl || this.offsetXxl);
  }

  render() {
    return (
      <Host>
        <slot></slot>
      </Host>
    );
  }
}
